interface OWidgetFrameProps {
    id: string;
    title?: string;
    locked: boolean;
    onLockToggle: (id: string) => void;
    zoom: number;
    colSpan: number;
    rowSpan: number;
    onZoomChange?: (id: string, zoom: number) => void;
    onClose?: (id: string) => void;
    /** 关闭确认文案,默认"确认关闭吗?" */
    closeConfirmText?: string;
    children: ReactNode;
    className?: string;
}
declare const OWidgetFrame: react.ForwardRefExoticComponent<OWidgetFrameProps & react.RefAttributes<HTMLDivElement>>;

interface WidgetLayout {
    id: string;
    /** 网格列起始(1-based) */
    col: number;
    /** 网格行起始(1-based) */
    row: number;
    /** 占几列 */
    colSpan: number;
    /** 占几行 */
    rowSpan: number;
    /** 内容缩放比例 0.5–2.0,默认 1 */
    zoom: number;
    /** false = 已被 X 关闭 */
    visible: boolean;
    /** 该框是否锁定(每框独立)。锁定=不可拖/缩放。默认 true */
    locked: boolean;
}
interface WidgetGridState {
    locked: boolean;
    widgets: Record<string, WidgetLayout>;
}

interface OWidgetGridProps {
    widgets: Record<string, WidgetLayout>;
    onWidgetChange: (id: string, patch: Partial<WidgetLayout>) => void;
    gridCols?: number;
    rowHeight?: number;
    gap?: number;
    children: (item: {
        id: string;
        layout: WidgetLayout;
    }) => ReactNode;
    className?: string;
}
declare function OWidgetGrid({ widgets, onWidgetChange, gridCols, rowHeight, gap, children, className, }: OWidgetGridProps): react__default.JSX.Element;

/**
 * WidgetContext — grid 向 frame 提供坐标计算回调。
 * 注意:locked 改为每框独立(OWidgetFrame 自己的 prop),
 * 不再放 context。context 只管"拖拽/缩放时的坐标换算"。
 */
interface WidgetContextValue {
    onDragStart: (id: string, e: PointerEvent) => void;
    onResizeStart: (id: string, e: PointerEvent) => void;
}
declare function useWidgetContext(): WidgetContextValue;

interface UseWidgetStorageOptions {
    /** localStorage key,不同 dashboard 用不同 key */
    storageKey: string;
    /** 初始布局(首次加载 or localStorage 为空时使用) */
    initialLayouts: WidgetLayout[];
    /** dashboard 初始锁定状态,默认 true */
    initialLocked?: boolean;
}
interface UseWidgetStorageReturn {
    locked: boolean;
    setLocked: (v: boolean) => void;
    widgets: Record<string, WidgetLayout>;
    updateWidget: (id: string, patch: Partial<WidgetLayout>) => void;
    /** 切换某框锁定态 */
    toggleLock: (id: string) => void;
    resetLayout: () => void;
}
declare function useWidgetStorage({ storageKey, initialLayouts, initialLocked, }: UseWidgetStorageOptions): UseWidgetStorageReturn;

